export const ETHIOPIAN_MEDICINE_LABELS: string[] = Array.from(
  new Set(
    ETHIOPIAN_ESSENTIAL_MEDICINES.map((m) => m.display)
  )
);

export const ETHIOPIAN_GENERIC_NAMES: string[] = Array.from(
  new Set(
    ETHIOPIAN_ESSENTIAL_MEDICINES.map((m) => m.generic_name)
  )
);

/**
 * Unified list of medication options for Combobox / Select pickers.
 * Includes both clean generic names (e.g., "Amoxicillin", "Paracetamol", "Metformin")
 * and detailed formulated names (e.g., "Amoxicillin 500mg (Capsule)", "Ceftriaxone 1g (Injection)").
 */
export const ETHIOPIAN_MEDICINE_OPTIONS: string[] = Array.from(
  new Set([
    ...ETHIOPIAN_GENERIC_NAMES,
    ...ETHIOPIAN_MEDICINE_LABELS,
  ])
).sort((a, b) => a.localeCompare(b));

export const ETHIOPIAN_CATEGORIES: string[] = Array.from(
  new Set(ETHIOPIAN_ESSENTIAL_MEDICINES.map((m) => m.major_category))
).sort((a, b) => a.localeCompare(b));

// Map for O(1) metadata lookup by generic name or display string
const MEDICINE_LOOKUP: Record<string, EthiopianMedicine> = {};
for (const m of ETHIOPIAN_ESSENTIAL_MEDICINES) {
  MEDICINE_LOOKUP[m.generic_name.toLowerCase().trim()] = m;
  MEDICINE_LOOKUP[m.display.toLowerCase().trim()] = m;
  MEDICINE_LOOKUP[m.name_with_aware.toLowerCase().trim()] = m;
}

/**
 * Returns default prescription settings (form, dosage, period, strength, category) for a chosen medicine.
 */
export function getEthiopianMedicineDefaults(nameOrDisplay: string): EthiopianMedicine | undefined {
  if (!nameOrDisplay) return undefined;
  const key = nameOrDisplay.toLowerCase().trim();
  if (MEDICINE_LOOKUP[key]) return MEDICINE_LOOKUP[key];

  // Try exact generic name match ignoring case
  const exactGen = ETHIOPIAN_ESSENTIAL_MEDICINES.find(
    (m) => m.generic_name.toLowerCase().trim() === key
  );
  if (exactGen) return exactGen;

  // Try prefix or substring match
  for (const m of ETHIOPIAN_ESSENTIAL_MEDICINES) {
    const gen = m.generic_name.toLowerCase().trim();
    if (key === gen || key.startsWith(gen) || gen.startsWith(key)) {
      return m;
    }
  }

  // Substring match
  for (const m of ETHIOPIAN_ESSENTIAL_MEDICINES) {
    const gen = m.generic_name.toLowerCase().trim();
    if (key.includes(gen) || gen.includes(key)) {
      return m;
    }
  }

  return undefined;
}

/**
 * Returns the exact Dosage Form and Strength from the Ethiopian Essential Medicines List.
 * If the medicine has multiple forms or multiple entries in the list, returns them
 * formatted across multiple lines so every form and strength is fully presented.
 */
export function getDosageFormAndStrength(nameOrDisplay: string): string {
  if (!nameOrDisplay) return "";
  const key = nameOrDisplay.toLowerCase().trim();

  const matches = ETHIOPIAN_ESSENTIAL_MEDICINES.filter((m) => {
    const gen = m.generic_name.toLowerCase().trim();
    const disp = m.display.toLowerCase().trim();
    return gen === key || disp === key || key.startsWith(gen) || gen.startsWith(key);
  });

  if (matches.length > 0) {
    const allForms: string[] = [];
    for (const m of matches) {
      if (m.dosage_form_and_strength) {
        const parts = m.dosage_form_and_strength.split(/\r?\n/).map((s) => s.trim()).filter(Boolean);
        allForms.push(...parts);
      }
    }
    const unique = Array.from(new Set(allForms));
    if (unique.length > 0) {
      return unique.join("\n");
    }
  }

  const def = getEthiopianMedicineDefaults(nameOrDisplay);
  return def?.dosage_form_and_strength?.trim() || "";
}

/**
 * Filter medicines by query (matches generic name, category, strength, AWaRe class)
 */
export function searchEthiopianMedicines(
  query: string,
  options?: {
    category?: string;
    aware?: "Access" | "Watch" | "Reserve" | "All";
    limit?: number;
  }
): EthiopianMedicine[] {
  const q = query.trim().toLowerCase();
  const limit = options?.limit || 50;

  return ETHIOPIAN_ESSENTIAL_MEDICINES.filter((m) => {
    if (options?.aware && options.aware !== "All" && m.aware !== options.aware) {
      return false;
    }
    if (
      options?.category &&
      options.category !== "All" &&
      !m.major_category.toLowerCase().includes(options.category.toLowerCase())
    ) {
      return false;
    }
    if (!q) return true;

    return (
      m.generic_name.toLowerCase().includes(q) ||
      m.dosage_form_and_strength.toLowerCase().includes(q) ||
      m.major_category.toLowerCase().includes(q) ||
      m.sub_category.toLowerCase().includes(q) ||
      (m.aware && m.aware.toLowerCase().includes(q))
    );
  }).slice(0, limit);
}

/**
 * Get medicines belonging to a major category or code
 */
export function getMedicinesByCategory(categoryOrCode: string): EthiopianMedicine[] {
  const c = categoryOrCode.trim().toLowerCase();
  return ETHIOPIAN_ESSENTIAL_MEDICINES.filter(
    (m) =>
      m.major_category.toLowerCase() === c ||
      m.major_code.toLowerCase() === c ||
      m.major_category.toLowerCase().includes(c)
  );
}

/**
 * Get AWaRe classified antibiotics (Access, Watch, Reserve)
 */
export function getAWaReMedicines(awareGroup: "Access" | "Watch" | "Reserve"): EthiopianMedicine[] {
  return ETHIOPIAN_ESSENTIAL_MEDICINES.filter((m) => m.aware === awareGroup);
}

